mapper.select:
select Month(od.created_at) as MONTH
from order_detail od
    left join order_coupon oc on od.id = oc.order_id
where od.created_at BETWEEN #{startedAt} and #{endedAt}
group by MONTH
order by MONTH;

select count(od.id) as totalOrderCnt
from order_detail od
         left join order_coupon oc on od.id = oc.order_id
where od.created_at BETWEEN #{startedAt} and #{endedAt}
group by Month (od.created_at)
order by Month (od.created_at);

select SUM(od.total_payment_price) as totalPaymentPrice
from order_detail od
         left join order_coupon oc
                   on od.id = oc.order_id
where od.created_at BETWEEN #{startedAt}
          and #{endedAt}
group by Month (od.created_at)
order by Month (od.created_at);

select count(oc.id) as totalCouponUseCnt
from order_detail od
         left join order_coupon oc
                   on od.id = oc.order_id
where od.created_at BETWEEN #{startedAt}
          and #{endedAt}
group by Month (od.created_at)
order by Month (od.created_at);

select SUM(od.total_discount_price) as totalCouponPrice
from order_detail od
         left join order_coupon oc
                   on od.id = oc.order_id
where od.created_at BETWEEN #{startedAt}
          and #{endedAt}
group by Month (od.created_at)
order by Month (od.created_at);
